using namespace std;

struct MinStack {
    stack<int> s;
    stack<int> ms;
    void push(int v) {
        s.push(v);
        int mn = ms.empty() ? v : min(v, ms.top());
        ms.push(mn);
    }
    void pop() {
        s.pop();
        ms.pop();
    }
    int top() { return s.top(); }
    int getMin() { return ms.top(); }
};

